import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.CvydjLy7.js";const h=JSON.parse('{"title":"十二、NoSQL 要点","description":"","frontmatter":{"title":"十二、NoSQL 要点"},"headers":[],"relativePath":"ch06/12.md","filePath":"ch06/12.md","lastUpdated":1789497795000}'),r={name:"ch06/12.md"};function s(n,t,c,i,p,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="十二、nosql-要点" tabindex="-1">十二、NoSQL 要点 <a class="header-anchor" href="#十二、nosql-要点" aria-label="Permalink to &quot;十二、NoSQL 要点&quot;">​</a></h1><p>官方 NoSQL 章节覆盖的技术，以及选型判断：</p><table tabindex="0"><thead><tr><th>技术</th><th>解决什么问题</th><th>什么时候不该用</th></tr></thead><tbody><tr><td>Redis</td><td>缓存、分布式锁、计数器、会话共享</td><td>当主数据库用——持久化和查询能力都不合适</td></tr><tr><td>MongoDB</td><td>文档型数据、字段不固定的场景（日志、表单、内容）</td><td>需要多表事务的强一致业务</td></tr><tr><td>Elasticsearch</td><td>全文检索、日志分析、聚合统计</td><td>当主数据库用；写入量大但不需要检索时成本过高</td></tr><tr><td>Cassandra</td><td>海量写入、多数据中心</td><td>需要复杂查询和事务</td></tr><tr><td>Neo4j</td><td>图关系（社交网络、推荐路径）</td><td>关系简单时纯属增加复杂度</td></tr></tbody></table><p>Spring Boot 对它们的接入方式一致：加对应的 <code>spring-boot-starter-data-*</code> 依赖，配 <code>spring.data.&lt;技术&gt;.*</code>，用 Spring Data 的 Repository 接口。</p><p><strong>本项目没有引入任何 NoSQL</strong>（缓存那一块在第 7 篇讲 <code>@Cacheable</code> 时用简单的内存实现说明原理）。原因很实际：教学项目的重点是让每个概念都能在本机跑起来、看得见效果；引入 Redis 就把环境依赖带进来了。需要上手时，官方 how-to 章节有各技术的完整示例。</p>',5)])])}const S=d(r,[["render",s]]);export{h as __pageData,S as default};
